import re

# 读取 styles.css
with open('/root/.openclaw/workspace/chinahospitalsguide/styles.css', 'r') as f:
    css = f.read()

# 检查常见排版问题
issues = []

# 1. 检查是否有未闭合的括号
open_braces = css.count('{')
close_braces = css.count('}')
if open_braces != close_braces:
    issues.append(f"❌ CSS 括号不匹配: 开启{open_braces} vs 关闭{close_braces}")

# 2. 检查是否有语法错误（如缺少分号）
# 查找属性值后面没有分号的情况（在规则块内）
lines = css.split('\n')
for i, line in enumerate(lines, 1):
    stripped = line.strip()
    if stripped and not stripped.startswith('/*') and not stripped.startswith('*') and not stripped.startswith('*/'):
        if ':' in stripped and not stripped.endswith(';') and not stripped.endswith('{') and not stripped.endswith('}') and not stripped.startswith('@'):
            # 可能是缺少分号
            if not stripped.endswith('*/') and not stripped.startswith('/*'):
                issues.append(f"⚠️ 行 {i}: 可能缺少分号: {stripped[:60]}")

# 3. 检查 media query 嵌套
media_queries = re.findall(r'@media[^{]*\{', css)
issues.append(f"📊 发现 {len(media_queries)} 个 media query")

# 4. 检查是否有重复的属性定义
duplicate_props = {}
rules = re.findall(r'([^{]+)\{([^}]*)\}', css, re.DOTALL)
for selector, props in rules:
    selector = selector.strip()
    prop_list = re.findall(r'([\w-]+)\s*:', props)
    for prop in prop_list:
        key = f"{selector}::{prop}"
        if key in duplicate_props:
            duplicate_props[key] += 1
        else:
            duplicate_props[key] = 1

duplicates = {k: v for k, v in duplicate_props.items() if v > 1}
if duplicates:
    issues.append(f"⚠️ 发现 {len(duplicates)} 个重复属性定义")
    for k, v in list(duplicates.items())[:5]:
        issues.append(f"   - {k}: {v}次")

# 5. 检查关键区域的 CSS
key_classes = ['.hero', '.quick-access', '.features', '.testimonials', '.hospitals', '.form-section']
print("=" * 60)
print("关键 CSS 类检查:")
print("=" * 60)
for cls in key_classes:
    pattern = re.escape(cls) + r'[^{]*\{([^}]*)\}'
    match = re.search(pattern, css, re.DOTALL)
    if match:
        props = match.group(1).strip()
        print(f"\n{cls}:")
        for line in props.split('\n'):
            line = line.strip()
            if line:
                print(f"  {line}")
    else:
        # 可能有多行规则
        start = css.find(cls + ' {')
        if start == -1:
            start = css.find(cls + '\n')
        if start != -1:
            brace_start = css.find('{', start)
            if brace_start != -1:
                # 找到匹配的 }
                depth = 1
                pos = brace_start + 1
                while pos < len(css) and depth > 0:
                    if css[pos] == '{':
                        depth += 1
                    elif css[pos] == '}':
                        depth -= 1
                    pos += 1
                props = css[brace_start+1:pos-1].strip()
                print(f"\n{cls}:")
                for line in props.split('\n'):
                    line = line.strip()
                    if line:
                        print(f"  {line}")

print("\n" + "=" * 60)
print("CSS 问题汇总:")
print("=" * 60)
for issue in issues[:20]:
    print(issue)

print(f"\n总计问题: {len(issues)}")
"}

