# 检查移动端 media query 的完整性
media_queries = []
for match in re.finditer(r'@media\s*\([^)]*\)\s*\{', css):
    start = match.start()
    # 找到匹配的 }
    depth = 1
    pos = match.end()
    while pos < len(css) and depth > 0:
        if css[pos] == '{':
            depth += 1
        elif css[pos] == '}':
            depth -= 1
            if depth == 0:
                media_queries.append({
                    'start': start,
                    'end': pos,
                    'query': css[start:match.end()],
                    'length': pos - start
                })
                break
        pos += 1

print(f"找到 {len(media_queries)} 个 media query:")
for i, mq in enumerate(media_queries):
    print(f"\n{i+1}. {mq['query'][:60]}...")
    print(f"   位置: {mq['start']}-{mq['end']}, 长度: {mq['length']}")
    # 检查内容
    content = css[mq['start']:mq['end']]
    # 检查是否有未闭合的规则
    inner = content[content.find('{')+1:]
    open_count = inner.count('{')
    close_count = inner.count('}')
    if open_count != close_count:
        print(f"   ⚠️ 内部括号不匹配: open={open_count}, close={close_count}")
    else:
        print(f"   ✅ 内部括号匹配")
"}

